/* Signature Georgian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Giorginino": "From Giorgi + Nino.", "Davittamar": "From Davit + Tamar.", "Iraklimta": "From Irakli + mta (mountain).", "Mariammze": "From Mariam + mze (sun).", "Ninomtvare": "From Nino + mtvare (moon).", "Tamarzgva": "From Tamar + zgva (sea).", "Giorginishvili": "Signature surname in -shvili style.", "Davittamaridze": "Signature surname in -dze style.", "Iraklimtashvili": "Signature surname in -shvili style.", "Mariammzidze": "Signature surname in -dze style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Giorginino';
console.log(lookup(q));

